select case when orders.discount >= 0.39 then 'high' when orders.discount >= 0.17 then 'mid' else 'low' end as discount_bucket, count(payments.amount) as amount_count from payments left join orders on payments.order_id = orders.id join customers on customers.id = orders.customer_id group by case when orders.discount >= 0.39 then 'high' when orders.discount >= 0.17 then 'mid' else 'low' end order by discount_bucket desc, amount_count desc;
